"""Public specification and input generator for fused gated RMSNorm."""
import torch


class Model(torch.nn.Module):
    def forward(self, gate, value, residual, weight, eps):
        fused = residual + torch.nn.functional.silu(gate) * value
        inv_rms = torch.rsqrt(fused.float().square().mean(dim=1, keepdim=True) + eps)
        return (fused * inv_rms * weight).to(gate.dtype)


def get_inputs(rows=1024, width=512, seed=0, eps=1.0e-5):
    generator = torch.Generator(device="cuda")
    generator.manual_seed(seed)
    make = lambda shape: torch.randn(shape, device="cuda", dtype=torch.float16,
                                      generator=generator)
    return [make((rows, width)), make((rows, width)), make((rows, width)),
            make((width,)), eps]

import ast
import importlib.util
import math
from pathlib import Path
import statistics
import time

import torch

from reference import Reference


CANDIDATE = Path("/workspace/solution.py")
ALLOWED_IMPORTS = {"torch", "triton", "triton.language", "math", "typing"}
BANNED_NAMES = {
    "exec", "eval", "compile", "__import__", "open", "os", "sys", "subprocess",
    "ctypes", "socket", "importlib", "pickle", "shutil", "getattr", "setattr",
    "delattr", "globals", "locals", "vars", "input", "breakpoint", "help", "load",
}
BANNED_ATTRIBUTES = {
    "save", "load", "load_library", "from_file", "set_", "share_memory_",
    "distributed", "multiprocessing", "serialization",
}
BANNED_TEXT = ("/logs", "/tests", "/solution", "reward.json", "reward.txt")


def is_triton_load(node):
    """Permit the GPU memory primitive while rejecting serialization loaders."""
    return (node.attr == "load" and isinstance(node.value, ast.Name)
            and node.value.id == "tl")


def validate_source(path):
    if not path.is_file() or path.stat().st_size > 100_000:
        raise ValueError("missing or oversized solution.py")
    source = path.read_text(encoding="utf-8")
    tree = ast.parse(source, filename=str(path))
    model_classes = [node for node in tree.body
                     if isinstance(node, ast.ClassDef) and node.name == "ModelNew"]
    if len(model_classes) != 1:
        raise ValueError("define exactly one top-level ModelNew class")
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            if any(alias.name not in ALLOWED_IMPORTS for alias in node.names):
                raise ValueError("import outside allowlist")
        elif isinstance(node, ast.ImportFrom):
            # Keep helpers qualified so forbidden APIs cannot be renamed away.
            raise ValueError("from-imports are not allowed")
        elif isinstance(node, ast.Name) and node.id in BANNED_NAMES:
            raise ValueError("banned name")
        elif isinstance(node, ast.Attribute):
            if node.attr.startswith("__") and node.attr != "__init__":
                raise ValueError("banned dunder attribute")
            if node.attr in BANNED_ATTRIBUTES and not is_triton_load(node):
                raise ValueError("banned attribute")
        elif isinstance(node, (ast.Assign, ast.AnnAssign, ast.AugAssign)):
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            if any(isinstance(target, (ast.Attribute, ast.Subscript)) for target in targets):
                raise ValueError("attribute and subscript mutation is not allowed")
        elif isinstance(node, ast.Constant) and isinstance(node.value, str):
            lowered = node.value.lower()
            if any(text in lowered for text in BANNED_TEXT):
                raise ValueError("sensitive path literal")
    return source


def load_candidate():
    validate_source(CANDIDATE)
    spec = importlib.util.spec_from_file_location("candidate_submission", CANDIDATE)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    model = module.ModelNew().cuda().eval()
    if not isinstance(model, torch.nn.Module):
        raise TypeError("ModelNew must be a torch.nn.Module")
    return model


def make_inputs(rows, width, seed, eps):
    generator = torch.Generator(device="cuda")
    generator.manual_seed(seed)
    make = lambda shape: torch.randn(shape, device="cuda", dtype=torch.float16,
                                      generator=generator)
    return (make((rows, width)), make((rows, width)), make((rows, width)),
            make((width,)), eps)


def timed_samples(function, args, count=20):
    for _ in range(8):
        function(*args)
    torch.cuda.synchronize()
    samples = []
    for _ in range(count):
        torch.cuda.synchronize()
        start = time.perf_counter_ns()
        function(*args)
        torch.cuda.synchronize()
        samples.append((time.perf_counter_ns() - start) / 1.0e6)
    return samples


def main():
    if not torch.cuda.is_available():
        raise RuntimeError("CUDA accelerator unavailable")
    torch.set_grad_enabled(False)
    reference = Reference().cuda().eval()
    candidate = load_candidate()

    correctness_cases = [
        (113, 256, 1701, 8.0e-6),
        (777, 512, 2903, 1.0e-5),
        (1025, 1024, 4109, 1.3e-5),
        (2049, 256, 7919, 9.0e-6),
        (333, 1024, 12347, 1.1e-5),
    ]
    for rows, width, seed, eps in correctness_cases:
        args = make_inputs(rows, width, seed, eps)
        expected = reference(*args)
        actual = candidate(*args)
        if not isinstance(actual, torch.Tensor) or actual.shape != expected.shape:
            raise AssertionError("wrong output type or shape")
        if actual.device.type != "cuda" or actual.dtype != torch.float16:
            raise AssertionError("output must be CUDA float16")
        if not torch.isfinite(actual).all().item():
            raise AssertionError("non-finite output")
        torch.testing.assert_close(actual, expected, rtol=8.0e-3, atol=8.0e-3)

    benchmark_cases = [(512, 256, 501), (1024, 512, 607), (2048, 1024, 709)]
    ref_means = []
    cand_means = []
    for rows, width, seed in benchmark_cases:
        args = make_inputs(rows, width, seed, 1.0e-5)
        ref_times = timed_samples(reference, args)
        cand_times = timed_samples(candidate, args)
        ref_mean = statistics.fmean(ref_times)
        cand_mean = statistics.fmean(cand_times)
        ref_means.append(ref_mean)
        cand_means.append(cand_mean)
        print(f"shape=({rows},{width}) reference_ms={ref_mean:.5f} "
              f"reference_std={statistics.pstdev(ref_times):.5f} "
              f"candidate_ms={cand_mean:.5f} "
              f"candidate_std={statistics.pstdev(cand_times):.5f}")
    ratio = statistics.fmean(cand_means) / statistics.fmean(ref_means)
    print(f"aggregate_runtime_ratio={ratio:.5f}")
    if not math.isfinite(ratio) or not 0.05 <= ratio <= 0.60:
        raise AssertionError(f"runtime ratio {ratio:.5f} outside [0.05, 0.60]")


if __name__ == "__main__":
    main()

